'use client';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { 
    Calendar, User, CheckCircle, ShieldCheck, Activity, 
    TrendingUp, DollarSign, Users 
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge"; // Note: I might need to install badge if I didn't. I'll stick to basic classes if badge is missing, but I'll use standard Tailwind for now.

export default function AdminDashboard() {
  const params = useParams();
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(false);
  
  const adminPathParam = params?.adminPath;
  const basePath = adminPathParam ? `/${adminPathParam}` : '';

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    setLoading(true);
    try {
      const res = await fetch('http://localhost:5000/api/bookings'); 
      if (res.ok) {
        const data = await res.json();
        setBookings(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
              <h1 className="text-3xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                  Dashboard Overview
              </h1>
              <p className="text-muted-foreground mt-2">Welcome back to your command center.</p>
            </div>
            <Button variant="outline" onClick={fetchBookings} className="gap-2 border-slate-700 hover:bg-slate-800 text-slate-200">
              <Activity className="h-4 w-4" /> Refresh Data
            </Button>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard 
                title="Total Bookings" 
                value={bookings.length} 
                icon={<Calendar className="h-5 w-5 text-cyan-400" />} 
                trend="+12% from last week"
            />
            <StatCard 
                title="Active Users" 
                value="120" 
                icon={<Users className="h-5 w-5 text-blue-400" />} 
                trend="+5 new today"
            />
            <StatCard 
                title="Total Revenue" 
                value={`₹${bookings.reduce((sum, b) => sum + Number(b.price || 0), 0).toLocaleString()}`} 
                icon={<DollarSign className="h-5 w-5 text-green-400" />} 
                trend="+8% this month"
            />
            <StatCard 
                title="Pending Actions" 
                value="3" 
                icon={<ShieldCheck className="h-5 w-5 text-orange-400" />} 
                trend="Requires attention"
            />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Quick Actions */}
            <Card className="bg-slate-900/40 border-slate-800 backdrop-blur-sm lg:col-span-1">
                <CardHeader>
                    <CardTitle className="text-xl text-white">Quick Actions</CardTitle>
                </CardHeader>
                <CardContent className="grid grid-cols-1 gap-3">
                    <Link href={`${basePath}/hospitals`} className="w-full">
                        <Button className="w-full bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white font-semibold">
                            + Add New Hospital
                        </Button>
                    </Link>
                    <Link href={`${basePath}/services`} className="w-full">
                        <Button variant="outline" className="w-full border-slate-700 hover:bg-slate-800 text-slate-300">
                            + Add Service
                        </Button>
                    </Link>
                    <div className="flex gap-3">
                        <Link href={`${basePath}/bookings`} className="flex-1">
                            <Button variant="ghost" className="w-full bg-slate-800/50 hover:bg-slate-800 text-slate-300">
                                View Pending
                            </Button>
                        </Link>
                        <Link href={`${basePath}/users`} className="flex-1">
                            <Button variant="ghost" className="w-full bg-slate-800/50 hover:bg-slate-800 text-slate-300">
                                Manage Users
                            </Button>
                        </Link>
                    </div>
                </CardContent>
            </Card>

            {/* Recent Bookings Table */}
            <Card className="bg-slate-900/40 border-slate-800 backdrop-blur-sm lg:col-span-2">
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="text-xl text-white">Recent Bookings</CardTitle>
                    <Link href={`${basePath}/bookings`} className="text-cyan-400 text-sm hover:underline">View All</Link>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow className="border-slate-800 hover:bg-slate-900/50">
                                <TableHead className="text-slate-400">ID</TableHead>
                                <TableHead className="text-slate-400">Patient</TableHead>
                                <TableHead className="text-slate-400">Service</TableHead>
                                <TableHead className="text-slate-400 text-right">Amount</TableHead>
                                <TableHead className="text-slate-400 text-center">Status</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {bookings.slice(0, 5).map((booking) => (
                                <TableRow key={booking.id} className="border-slate-800 hover:bg-slate-800/30">
                                    <TableCell className="font-medium text-slate-300">#{booking.id}</TableCell>
                                    <TableCell className="text-slate-300">{booking.patient_name}</TableCell>
                                    <TableCell className="text-slate-400">{booking.service_name}</TableCell>
                                    <TableCell className="text-right font-bold text-white">₹{booking.price}</TableCell>
                                    <TableCell className="text-center">
                                        <BadgeStatus status={booking.status} />
                                    </TableCell>
                                </TableRow>
                            ))}
                            {bookings.length === 0 && (
                                <TableRow>
                                    <TableCell colSpan={5} className="text-center py-8 text-slate-500">
                                        No bookings found.
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
        </div>
    </div>
  );
}

function StatCard({ title, value, icon, trend }) {
    return (
        <Card className="bg-slate-900/40 border-slate-800 backdrop-blur-sm">
            <CardContent className="p-6">
                <div className="flex items-center justify-between space-y-0 pb-2">
                    <p className="text-sm font-medium text-slate-400">{title}</p>
                    <div className="bg-slate-800/50 p-2 rounded-lg">{icon}</div>
                </div>
                <div className="flex flex-col mt-3">
                    <h3 className="text-2xl font-bold text-white">{value}</h3>
                    <p className="text-xs text-slate-500 mt-1">{trend}</p>
                </div>
            </CardContent>
        </Card>
    );
}


function BadgeStatus({ status }) {
    const variant = status === 'Completed' ? 'default' : 'secondary';
    // Mapping our status to badge variants. 'default' is primary color.
    // We can also create custom variants in badge.js if we want specific colors.
    // For now, let's stick to simple variants or customize with className.
    
    let className = "";
    if (status === 'Completed') {
        className = "bg-green-500/10 text-green-500 hover:bg-green-500/20 border-green-500/20";
    } else {
        className = "bg-cyan-500/10 text-cyan-500 hover:bg-cyan-500/20 border-cyan-500/20";
    }

    return (
        <Badge variant="outline" className={className}>
            {status || 'Pending'}
        </Badge>
    );
}
